        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user.strip() + " name=" + text);
        return saved;
    }

    /**
     * Add a person of the sheet to a pool with a share (two decimals, more than 0.00 and at most
     * 100.00), from the optional from-date to the optional to-date; refused when they are already in it,
     * the share is bad, or the to-date is before the from-date.
     */
    @Transactional
    public void addMember(String sheetId, String user, Long poolId, Long personId, String share, LocalDate from,
            LocalDate to) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId).orElseThrow(PoolNotFoundException::new);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        BigDecimal value = shareOf(share);
        checkDates(from, to);
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) throw new DuplicatePoolMemberException();
        PoolMember member = new PoolMember(pool.getId(), sheetId, person.getId(), value);
        member.setDates(from, to);
        members.saveAndFlush(member);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user.strip() + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + value.toPlainString() + datesField(from, to));
    }

    /**
     * Add another pool of the sheet to a pool with a share; refused when the share is bad, the pool is
     * already a member of a pool, it would contain itself through any chain, or the chain of pools would
     * be more than three deep, or the to-date is before the from-date.
     */
    @Transactional
    public void addPoolMember(String sheetId, String user, Long poolId, Long memberPoolId, String share,
            LocalDate from, LocalDate to) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId).orElseThrow(PoolNotFoundException::new);
        Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId).orElseThrow(PoolNotFoundException::new);
        BigDecimal value = shareOf(share);
        checkDates(from, to);
        if (members.existsByMemberPoolId(member.getId())) throw new PoolNestingException();
        Map<Long, Long> parentOf = new HashMap<>();
        Map<Long, List<Long>> childrenOf = new HashMap<>();
        for (PoolMember m : members.findBySheetIdOrderByIdAsc(sheetId)) {
            if (m.getMemberPoolId() == null) continue;
            parentOf.put(m.getMemberPoolId(), m.getPoolId());
            childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
        }
        // the pool and the pools above it: the member must not be among them
        int above = 0;
        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
            if (at.equals(member.getId())) throw new PoolNestingException();
            above++;
        }
        if (above + depth(member.getId(), childrenOf) > 3) throw new PoolNestingException();
        PoolMember added = PoolMember.ofPool(pool.getId(), sheetId, member.getId(), value);
        added.setDates(from, to);
        members.saveAndFlush(added);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user.strip() + " pool=" + pool.getName()
                + " name=" + member.getName() + " share=" + value.toPlainString() + datesField(from, to));
    }

    /** Refused when both dates are given and the to-date is before the from-date. */
    private static void checkDates(LocalDate from, LocalDate to) {
        if (from != null && to != null && to.isBefore(from)) throw new PoolMemberDatesException();
    }

    public record CrewLine(Long id, String name, Member lead, List<Member> members) {}

    private final SheetRepository sheets;
    private final CrewRepository crews;
    private final CrewMemberRepository members;
    private final PersonRepository people;
    private final PoolRepository pools;
    private final Audit audit;

    public CrewService(SheetRepository sheets, CrewRepository crews, CrewMemberRepository members,
            PersonRepository people, PoolRepository pools, Audit audit) {
        this.pools = pools;
        this.sheets = sheets;
        this.crews = crews;
        this.members = members;
        this.people = people;
        this.audit = audit;
    }

    /** The sheet's crews, in the order they were added; only people still on the sheet are shown. */
    @Transactional(readOnly = true)
    public List<CrewLine> crews(String sheetId) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<CrewMember>> byCrew = members.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(CrewMember::getCrewId));
        List<CrewLine> lines = new ArrayList<>();
        for (Crew crew : crews.findBySheetIdOrderByIdAsc(sheetId)) {
            Person lead = byId.get(crew.getLeadPersonId());
            List<Member> shown = new ArrayList<>();
            for (CrewMember m : byCrew.getOrDefault(crew.getId(), List.of())) {
                Person p = byId.get(m.getPersonId());
                if (p != null) shown.add(new Member(p.getId(), p.getName()));
            }
            lines.add(new CrewLine(crew.getId(), crew.getName(),
                    lead == null ? null : new Member(lead.getId(), lead.getName()), shown));
        }
        return lines;
    }

    /** Add a crew, its name trimmed, led by a person of the sheet; refused when blank or already a crew or a pool of the sheet. */
    @Transactional
    public Crew add(String sheetId, String user, String name, Long leadId) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        String text = name == null ? "" : name.strip();
        if (text.isEmpty()) throw new CrewNameBlankException();
        Person lead = people.findByIdAndSheetId(leadId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (crews.existsBySheetIdAndName(sheetId, text) || pools.existsBySheetIdAndName(sheetId, text)) throw new DuplicateCrewNameException();
        Crew saved = crews.saveAndFlush(new Crew(sheetId, text, lead.getId()));
        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user.strip() + " name=" + text
                + " lead=" + lead.getName());
        return saved;
    }

    /** Add a person of the sheet to a crew; refused when they are its lead or already in it. */
    @Transactional
    public void addMember(String sheetId, String user, Long crewId, Long personId) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Crew crew = crews.findByIdAndSheetId(crewId, sheetId).orElseThrow(CrewNotFoundException::new);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getId().equals(crew.getLeadPersonId())
                || members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
            throw new CrewMemberRefusedException();
        }
        members.saveAndFlush(new CrewMember(crew.getId(), sheetId, person.getId()));
        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user.strip() + " crew=" + crew.getName()
                + " name=" + person.getName());
    }
}
    @Transactional(readOnly = true)
    public LocalDate entryDate(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getEntryDate();
    }

    /** Change the pot (null: none); not dated. */
    @Transactional
    public BigDecimal setPot(String sheetId, String user, BigDecimal pot) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setPot(pot);
        sheets.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=pot value="
                + (pot == null ? "" : pot.toPlainString()));
        return pot;
    }

        return terms;
    }

    /** Record the floor from the date (null: the sheet's today); the live dues it moves are audited after its own line. */
    @Transactional
    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        record(sheet, user, Sheet.FLOOR, floor.toPlainString(), from);
        rollup.recordChanges(sheetId, user, before);
        return floor;
    }

